/**
 * exemples-postal.ts — Exemples d'ateliers (1 à 5) pour les services postaux et d'expédition (courrier, colis et
 * express, réseau de points de contact, international, e-logistique, services au domicile).
 *
 * Même format que `exemples-protection-sociale.ts` : textes ×5 dans la donnée, `profs` = sous-profession (id du
 * sous-secteur sans le préfixe `postal-`), éléments sans `profs` = socle commun de la famille. Exemples GÉNÉRIQUES :
 * aucune entreprise réelle n'est citée. Suggestions à qualifier, contenu « à relire par un expert du secteur ».
 *
 * Module pur → testé (exemples-postal.test.ts).
 */
import type { ExtItem, Tr } from '@/lib/exemples-sectoriels-ext'

const L = (fr: string, en: string, de: string, es: string, it: string): Tr => [fr, en, de, es, it]
type P = readonly string[] | null
const F = 'postal' as const
const mk = (category: ExtItem['category'], profs: P, data: Record<string, unknown>): ExtItem => ({ famille: F, category, ...(profs ? { profs } : {}), data })
const vm = (profs: P, nom: Tr, type: 'PROCESSUS' | 'INFORMATION', description: Tr, responsable: Tr, d: number, i: number, c: number, t: number) =>
  mk('valeursMetier', profs, { nom, type, description, responsable, disponibilite: d, integrite: i, confidentialite: c, tracabilite: t })
const bs = (profs: P, nom: Tr, type: string, description: Tr) => mk('biensSupports', profs, { nom, type, description })
const er = (profs: P, description: Tr, impacts: Tr[], graviteDefaut: number) => mk('evenementsRedoutes', profs, { description, impacts, graviteDefaut })
const sr = (profs: P, nom: Tr, categorie: string, description: Tr, motivation: Tr, ressources: Tr, pertinenceDefaut: number) =>
  mk('sourcesRisque', profs, { nom, categorie, description, motivation, ressources, pertinenceDefaut })
const ss = (profs: P, critere: 'C' | 'I' | 'D' | 'T', nom: Tr, description: Tr, vraisemblanceDefaut: number, graviteDefaut: number) =>
  mk('scenariosStrategiques', profs, { critere, nom, description, vraisemblanceDefaut, graviteDefaut })
const pp = (profs: P, nom: Tr, type: string, dependance: number, penetration: number, maturite: number, confiance: number) =>
  mk('partiesPrenantes', profs, { nom, type, dependance, penetration, maturite, confiance })
const ae = (profs: P, type: string, attack: string, nom: Tr, description: Tr) => mk('actionsElementaires', profs, { type, attack, nom, description })
const me = (profs: P, mesure: Tr, type: 'ORGANISATIONNELLE' | 'TECHNIQUE' | 'DETECTIVE', iso27005: string, description: Tr) =>
  mk('mesuresEcosysteme', profs, { mesure, type, iso27005, description })
const ms = (profs: P, nom: Tr, description: Tr, type: 'ORGANISATIONNELLE' | 'TECHNIQUE' | 'DETECTIVE', categorieEbios: 'GOUVERNANCE' | 'PROTECTION' | 'DEFENSE' | 'RESILIENCE', prioriteDefaut: 1 | 2 | 3, references?: string[]) =>
  mk('mesures', profs, { nom, description, type, categorieEbios, prioriteDefaut, ...(references ? { references } : {}) })

